const { execSync } = require('child_process');
const diff = execSync('git --no-pager diff origin/main...HEAD --unified=0', {encoding:'utf8', maxBuffer: 64*1024*1024});
const added = {}; let cur = null, nl = 0;
for (const l of diff.split('\n')) {
  const h = l.match(/^diff --git a\/(.*) b\/(.*)$/); if (h) { cur = h[2]; continue; }
  const hm = l.match(/^@@ -\d+(?:,\d+)? \+(\d+)(?:,\d+)? @@/); if (hm && cur) { nl = +hm[1]; continue; }
  if (!cur) continue;
  if (l.startsWith('+') && !l.startsWith('+++')) { (added[cur]=added[cur]||new Set()).add(nl); nl++; }
  else if (l.startsWith(' ') ) nl++;
}
[['js/smAgent.js',2767],['js/factoryState.js',1016]].forEach(([f,n])=>console.log((added[f]&&added[f].has(n)?'OK  ':'FAIL')+' '+f+':'+n));
EOF
