{"command":"cd /home/runner/work/dmtools-agents/dmtools-agents && cat > /tmp/checklines.js <<'EOF'
const { execSync } = require('child_process');
const specs = [
  ["js/sm/sources/githubSource.js", 840],
  ["js/common/validationLiveness.js", 282],
  ["js/sm/sources/githubSource.js", 874],
  ["js/sm/sources/githubSource.js", 877],
  ["js/unit-tests/test_smGithubSource.js", 51],
  ["js/smAgent.js", 3079],
  ["js/common/mutexRegistry.js", 15],
  [".fah/bash_jobs/running.json", 1],
  ["js/smAgent.js", 3090]
];
// added/right-side lines per file from the real diff
const diff = execSync('git --no-pager diff origin/main...HEAD --unified=0', {encoding:'utf8', maxBuffer: 64*1024*1024});
const added = {};
let cur = null, newLine = 0;
for (const l of diff.split('\n')) {
  const h = l.match(/^diff --git a\/(.*) b\/(.*)$/);
  if (h) { cur = h[2]; continue; }
  const hm = l.match(/^@@ -\d+(?:,\d+)? \+(\d+)(?:,\d+)? @@/);
  if (hm && cur) { newLine = parseInt(hm[1], 10); continue; }
  if (!cur) continue;
  if (l.startsWith('+') && !l.startsWith('+++')) {
    (added[cur] = added[cur] || new Set()).add(newLine);
    newLine++;
  } else if (l.startsWith('-') && !l.startsWith('---')) {
    // no increment
  } else if (l.startsWith(' ')) {
    newLine++;
  }
}
let ok = true;
for (const [f, n] of specs) {
  const s = added[f];
  const inDiff = s && s.has(n);
  console.log((inDiff ? 'OK  ' : 'FAIL') + ' ' + f + ':' + n);
  if (!inDiff) ok = false;
}
process.exit(ok ? 0 : 1);
EOF
node /tmp/checklines.js"}

