+ * armed is a holder even if missing from the candidate list.
+ */
+function labelHoldersOf(liveItems, mutexLabel) {
+    var label = str(mutexLabel) || DEFAULT_MUTEX_LABEL;
+    var out = [];
+    (liveItems || []).forEach(function (it) {
+        var labels = (it && it.labels) || [];
